// Bakes movement 065's stop outline: Brown's stop with its toe, trimmed where
// driver C (deepened to the stop's plane) sweeps through it during the index.
import {writeFile} from 'node:fs/promises';
import {makeTappetStudStop} from '../src/simulation/tappet-stud-stop.js';
const points=makeTappetStudStop({computeStopOutline:true}).root.userData.paths.stop.map(q=>q.map(v=>Number(v.toPrecision(15))));
await writeFile(new URL('../src/data/tappet-stud-stop-outline.js',import.meta.url),
  '// Generated by scripts/generate-tappet-stud-stop-outline.mjs.\n'
  +'// Movement 065 stop outline in the stop pivot frame: one flat plate whose toe point rides C.\n'
  +`export default ${JSON.stringify({points})};\n`);
console.log({points:points.length});
